<?php
/**
 * Tripcode generator for 6chan.
 *
 * How it works:
 *   - User types "usrname#password" in the name field
 *   - parse_tripcode() splits it into [display_name, tripcode]
 *   - The tripcode is generated by shelling out to tripcodes.exe (Windows)
 *     or tripcodes (Linux/Oracle Cloud) — the compiled Go binary
 *   - The '!' + tripcode is stored alongside the author name in the DB
 *
 * Binary location:
 *   Place tripcodes.exe (Windows) or tripcodes (Linux) in:
 *   /bin/tripcodes[.exe]
 *
 * To compile on Windows:
 *   go build -o bin/tripcodes.exe tripcodes.go
 *
 * To cross-compile for Linux (Oracle Cloud deploy):
 *   set GOOS=linux && set GOARCH=amd64 && go build -o bin/tripcodes tripcodes.go
 *
 * TinyGo WASM (optional & browser-side only):
 *   tinygo build -o bin/tripcodes.wasm -target wasm tripcodes.go
 */

defined('ROOT_PATH') || define('ROOT_PATH', dirname(__DIR__));

/**
 * Splits a raw name field into [display_name, tripcode|null].
 *
 * Rules:
 *   "Anon"           → ["Anon", null]
 *   "Name#pass"      → ["Name", "!XXXXXXXXXX"]
 *   "#pass"          → ["Anon", "!XXXXXXXXXX"]  (anonymous with trip)
 */
function parse_tripcode(string $raw): array {
    $pos = strpos($raw, '#');

    if ($pos === false) {
        $display = trim($raw) ?: 'Anon';
        return [$display, null];
    }

    $display  = trim(substr($raw, 0, $pos)) ?: 'Anon';
    $password = substr($raw, $pos + 1);

    // Strip a leading # if user typed ## (secure trip syntax, treat same for now)
    if (str_starts_with($password, '#')) {
        $password = substr($password, 1);
    }

    $password = trim($password);

    if ($password === '') {
        return [$display, null];
    }

    $trip = generate_tripcode($password);
    if ($trip === null) {
        return [$display, null];
    }

    return [$display, '!' . $trip];
}

/**
 * Calls the Go binary to compute a tripcode for the given password.
 * Returns a 10-character string, or null on failure.
 */
function generate_tripcode(string $password): ?string {
    // Sanitize: strip shell-dangerous chars from password before passing
    // We use proc_open so we never touch a shell, but let's be safe anyway bcuz fuck it who knows.
    if (strlen($password) > 128) {
        $password = substr($password, 0, 128);
    }

    $binary = _tripcode_binary_path();

    if (!file_exists($binary)) {
        error_log("[tripcode] Binary not found at: $binary");
        return null;
    }

    // Use proc_open — NO shell involved, so no injection risk
    $desc = [
        0 => ['pipe', 'r'], // stdin  (unused)
        1 => ['pipe', 'w'], // stdout (tripcode output)
        2 => ['pipe', 'w'], // stderr (error messages)
    ];

    $proc = proc_open([$binary, $password], $desc, $pipes);

    if (!is_resource($proc)) {
        error_log("[tripcode] Failed to start binary: $binary");
        return null;
    }

    fclose($pipes[0]);

    $output = stream_get_contents($pipes[1]);
    $errors = stream_get_contents($pipes[2]);
    fclose($pipes[1]);
    fclose($pipes[2]);

    $exit = proc_close($proc);

    if ($exit !== 0) {
        error_log("[tripcode] Binary exited $exit: $errors");
        return null;
    }

    $trip = trim($output);

    if (!preg_match('/^[0-9A-Za-z+\/]{10}$/', $trip)) {
        error_log("[tripcode] Unexpected output: " . json_encode($trip));
        return null;
    }

    return $trip;
}

function _tripcode_binary_path(): string {
    $is_windows = PHP_OS_FAMILY === 'Windows';
    $bin = ROOT_PATH . '/bin/tripcodes' . ($is_windows ? '.exe' : '');
    return $bin;
}
